void handleRoot() {
  server.send_P(200, "text/html", index_html);
}

// На любые DNS-запросы в режиме точки доступа отвечаем «все адреса — это я»
void handleDns() {
  dnsServer.processNextRequest();
}

void setup() {
  Serial.begin(115200);

  // ---------- ВАРИАНТ 2: точка доступа + DNS-перехват ----------
  if (apMode) {
    WiFi.softAP(WIFI_SSID, WIFI_PASS);
    IPAddress apIP = WiFi.softAPIP();          // обычно 192.168.4.1
    dnsServer.start(53, "*", apIP);            // любой адрес -> ESP32
    Serial.print("Подключись к Wi-Fi \"");
    Serial.print(WIFI_SSID);
    Serial.println("\" и открой: http://mama.dr");
  }
  // ---------- ВАРИАНТ 1: домашняя сеть + mDNS ----------
  else {
    WiFi.begin(WIFI_SSID, WIFI_PASS);
    Serial.print("Подключаемся к Wi-Fi");
    while (WiFi.status() != WL_CONNECTED) {
      delay(500);
      Serial.print(".");
    }
    Serial.println();
    Serial.print("IP: ");
    Serial.println(WiFi.localIP());

    // Регистрируем имя mama.local
    if (MDNS.begin("mama")) {
      Serial.println("Открытка доступна по адресу: http://mama.local");
    } else {
      Serial.println("mDNS не запустился, открывай по IP выше");
    }
  }

  server.on("/", handleRoot);
  // Редирект с любого «лишнего» адреса на главную (на случай если кто-то
  // зашёл на http://192.168.0.122/любое_слово)
  server.onNotFound([]() {
    server.sendHeader("Location", "/", true);
    server.send(302, "text/plain", "");
  });
  server.begin();
}

void loop() {
  server.handleClient();
  if (apMode) handleDns();
}
